export type BrandIconPath = { d: string; color: string };

export type BrandIcon = {
  title: string;
  viewBox: string;
  paths: BrandIconPath[];
};

/**
 * Logotipos oficiais: Simple Icons (CC0) e, para marcas que não estão nele,
 * Devicon (MIT). `color` é a cor da marca, ajustada para fundo escuro quando
 * a oficial é preta.
 */
const simple = (icon: SimpleIcon, color = `#${icon.hex}`): BrandIcon => ({
  title: icon.title,
  viewBox: "0 0 24 24",
  paths: [{ d: icon.path, color }],
});

